#include "stdafx.h"#include "HcdElementBase.h"struct SRSW_P{#include "PrivateVars/RSW.h"};class KRSW : public KHcdElementBase  , protected SRSW_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _RSW("RSW", KRSW::Create);IHcdElement *KRSW::Create(){  return new KRSW;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KRSW, 10 )void KRSW::InitParm(){#include "PrivateVars/RSW.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KRSW::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KRSW::StepCalc( SStepCalcParams &params ){  if( SEL < 1 )    OUT = IN1;  else if( SEL > 8 )    OUT = IN8;  else  {    tAnalog32 *ins = &IN1;    OUT = ins[SEL-1];  }}